        max: Optional['types.ParticipantMaxAggregateInput'] = None,
        having: Optional['types.ParticipantScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.ParticipantCountAggregateInput']] = None,
